package com.livefast.eattrash.raccoonforfriendica.domain.pushnotifications.crypto

/**
 * Handles WebPush (RFC 8291) cryptographic operations using Elliptic Curve Diffie-Hellman (ECDH)
 * and AES-GCM encryption natively via the Java Cryptography Architecture (JCA).
 */
interface WebPushCryptoUtil {

    /**
     * Representation of the key material generated by the client to establish a WebPush subscription.
     * NB: All strings should be Base64URL-encoded (without padding) for storage and transmission.
     */
    data class PushKeys(val publicKey: String, val privateKey: String, val authSecret: String)

    /**
     * Generate a new P-256 (prime256v1) Elliptic Curve key pair and a 16-byte random authentication secret.
     *
     * @return [PushKeys] containing the Base64URL-encoded key material.
     */
    fun generateKeys(): PushKeys

    /**
     * Decrypt an incoming WebPush AES-GCM payload.
     *
     * @param encryptedPayload The raw byte array received from the UnifiedPush distributor.
     * @param publicKey The Base64URL-encoded public key stored during subscription.
     * @param privateKey The Base64URL-encoded private key stored during subscription.
     * @param authSecret The Base64URL-encoded authentication secret stored during subscription.
     * @return The decrypted JSON payload as a UTF-8 String, or null if decryption fails.
     */
    fun decryptPayload(encryptedPayload: ByteArray, publicKey: String, privateKey: String, authSecret: String): String?
}
